    function SVF(svg, pie) { return '<figure class="svfig">' + svg + (pie ? '<figcaption>' + pie + '</figcaption>' : '') + '</figure>'; }
    function TB(nom, filas, fis) {
        return '<div class="tb2"><div class="tabla-wrap"><table><caption>' + nom + '</caption><thead><tr><th scope="col">Columna</th><th scope="col">Tipo</th><th scope="col">Long.</th><th scope="col">Clave</th></tr></thead><tbody>' +
            filas.map(function (f) { return '<tr><td>' + f[0] + '</td><td>' + f[1] + '</td><td>' + f[2] + '</td><td>' + (f[3] || '') + '</td></tr>'; }).join('') +
            '</tbody></table></div><div class="tabla-wrap"><table><caption>Diseño físico</caption><thead><tr><th scope="col">Parámetro</th><th scope="col">Valor</th></tr></thead><tbody>' +
            fis.map(function (f) { return '<tr><td>' + f[0] + '</td><td>' + f[1] + '</td></tr>'; }).join('') + '</tbody></table></div></div>';
    }

    /* Calculadora de costo de acceso (consulta crítica). Se maneja con un solo escuchador sobre la raíz, porque el motor arma el HTML después. */
    const C0 = { n: 5, k: 2, niv: 2, q: 20000, pf: 100, pv: 25 };
    const fmt = function (x) { return Math.round(x).toLocaleString('es-PE'); };
    function calcRes(v) {
        const rd = v.niv + 1;                                   // accesos de una lectura indexada = niveles del índice + 1
        const antes = (1 + v.k * v.n) * rd;                     // 1 lectura de la tabla principal + k tablas por cada una de las n filas
        const desp = rd;                                        // un solo registro de la tabla suplementaria
        return { rd: rd, antes: antes, desp: desp, veces: antes / desp, dAntes: antes * v.q, dDesp: desp * v.q, rl: v.pf + v.n * v.pv, barra: Math.max(3, Math.round(desp / antes * 100)) };
    }
    function calcPintar(w, r) {
        const set = function (k, t) { const e = w.querySelector('[data-o="' + k + '"]'); if (e) e.textContent = t; };
        set('rd', fmt(r.rd)); set('antes', fmt(r.antes)); set('desp', fmt(r.desp)); set('veces', fmt(r.veces)); set('dAntes', fmt(r.dAntes)); set('dDesp', fmt(r.dDesp)); set('rl', fmt(r.rl));
        const b = w.querySelector('[data-o="barra"]'); if (b) b.style.width = r.barra + '%';
    }
    function calcHTML() {
        const r = calcRes(C0);
        const campo = function (id, tit, ayuda, mn, mx) { return '<label>' + tit + '<input type="number" inputmode="numeric" data-c="' + id + '" min="' + mn + '" max="' + mx + '" step="1" value="' + C0[id] + '"><small>' + ayuda + '</small></label>'; };
        return '<div class="v-ficha vc2"><span class="v-pestana">Calculadora de costo de acceso</span><div class="calc" data-calc>' +
            '<div class="calc-in">' +
            campo('n', 'Filas por cliente (n)', 'Cuántos elementos tiene el vector (máximo 99)', 1, 99) +
            campo('k', 'Tablas por cada fila', 'Las que se leen por cada una de las n filas', 1, 10) +
            campo('niv', 'Niveles del índice', 'Cada lectura indexada cuesta niveles + 1 accesos', 1, 5) +
            campo('q', 'Consultas por día', 'Cuántas veces se ejecuta (muchos usuarios)', 1, 1000000) +
            campo('pf', 'Parte fija del registro (bytes)', 'Datos que no se repiten', 1, 1000) +
            campo('pv', 'Bytes por elemento del vector', 'Lo que ocupa cada elemento', 1, 500) +
            '</div>' +
            '<div class="calc-res"><div class="calc-box antes"><span class="etq">Antes: sin tabla suplementaria</span><b data-o="antes">' + fmt(r.antes) + '</b><span>accesos por consulta</span><div class="calc-barra"><i style="width:100%"></i></div></div>' +
            '<div class="calc-box desp"><span class="etq">Después: con tabla suplementaria</span><b data-o="desp">' + fmt(r.desp) + '</b><span>accesos por consulta</span><div class="calc-barra"><i data-o="barra" style="width:' + r.barra + '%"></i></div></div></div>' +
            '<p class="calc-linea">La consulta pasa a costar <b data-o="veces">' + fmt(r.veces) + '</b> veces menos. Con las consultas del día: <b data-o="dAntes">' + fmt(r.dAntes) + '</b> accesos antes frente a <b data-o="dDesp">' + fmt(r.dDesp) + '</b> después. Una lectura indexada cuesta <b data-o="rd">' + fmt(r.rd) + '</b> accesos.</p>' +
            '<p class="calc-linea">Longitud del registro suplementario: RL = PF + n × PV = <b data-o="rl">' + fmt(r.rl) + '</b> bytes.</p>' +
            '<p class="calc-nota">Es un modelo simplificado a partir de lo visto en el curso (el ejemplo de consulta de saldos de un banco). Úsalo para sustentar con números; el recorrido real de tu consulta puede ser otro y tienes que contarlo con tus propias tablas.</p>' +
            '</div></div>';
    }
    const raizCalc = document.querySelector('.asesoria-' + SLUG);
    if (raizCalc) raizCalc.addEventListener('input', function (e) {
        const w = e.target && e.target.closest ? e.target.closest('[data-calc]') : null;
        if (!w) return;
        const v = {};
        Array.prototype.forEach.call(w.querySelectorAll('input[data-c]'), function (i) {
            const mn = +i.min, mx = +i.max; let x = parseInt(i.value, 10); if (isNaN(x)) x = mn;
            v[i.getAttribute('data-c')] = Math.min(mx, Math.max(mn, x));
        });
        calcPintar(w, calcRes(v));
    });

