            const b = h('button', 'pq k' + (i % 4 + 1), '<span class="n">' + (i + 1) + '</span><h3>' + esc(q.titulo) + '</h3><p class="muted">' + esc(q.desc) + '</p><p class="muted">' + esc(q.tiempo) + '</p><span class="go-t">Empezar →</span>');
