        q.bloques.forEach(function (_, i) { d.appendChild(h('span', 'dot ' + (ex.res[i] === 'primer' ? 'hecho' : ex.res[i] === 'ayuda' ? 'ayuda' : i === ex.i ? 'act' : ''), String(i + 1))); });
        b.appendChild(d); return b;
